//! B3 (#39): OIDC sign-in mapped to registry users (ADR-0007 section 7).
//! Every key and token is generated by the test. IdP group claims are never
//! live; they reach the registry only through the audited import.
mod common;
use axum::http::{Method, StatusCode};
use common::*;
use ring::rand::SystemRandom;
use ring::signature::{EcdsaKeyPair, Ed25519KeyPair, KeyPair, ECDSA_P256_SHA256_FIXED_SIGNING};
use rsa::pkcs1v15::SigningKey as RsaSigningKey;
use rsa::signature::{SignatureEncoding, Signer};
use rsa::traits::PublicKeyParts;
use serde_json::{json, Value};
use weave_service::error::UNAUTHENTICATED_MESSAGE;
use weave_service::oidc::base64url_encode as b64;

const ISSUER: &str = "https://idp.example.test";
const AUDIENCE: &str = "weave-acme";

enum Key {
    Ed(Ed25519KeyPair),
    Ec(EcdsaKeyPair),
    Rsa(Box<RsaSigningKey<sha2::Sha256>>, Value),
}

impl Key {
    fn ed() -> Self {
        let rng = SystemRandom::new();
        let doc = Ed25519KeyPair::generate_pkcs8(&rng).unwrap();
        Key::Ed(Ed25519KeyPair::from_pkcs8(doc.as_ref()).unwrap())
    }
    fn ec() -> Self {
        let rng = SystemRandom::new();
        let doc = EcdsaKeyPair::generate_pkcs8(&ECDSA_P256_SHA256_FIXED_SIGNING, &rng).unwrap();
        Key::Ec(
            EcdsaKeyPair::from_pkcs8(&ECDSA_P256_SHA256_FIXED_SIGNING, doc.as_ref(), &rng).unwrap(),
        )
    }
    fn rsa() -> Self {
        let mut rng = rand_core::OsRng;
        let private = rsa::RsaPrivateKey::new(&mut rng, 2048).unwrap();
        let public = private.to_public_key();
        let jwk = json!({"kty": "RSA", "n": b64(&public.n().to_bytes_be()),
            "e": b64(&public.e().to_bytes_be())});
        Key::Rsa(Box::new(RsaSigningKey::<sha2::Sha256>::new(private)), jwk)
    }
    fn alg(&self) -> &str {
        match self {
            Key::Ed(_) => "EdDSA",
            Key::Ec(_) => "ES256",
            Key::Rsa(..) => "RS256",
        }
    }
    fn jwk(&self, kid: &str) -> Value {
        let mut jwk = match self {
            Key::Ed(k) => {
                json!({"kty": "OKP", "crv": "Ed25519", "x": b64(k.public_key().as_ref())})
            }
            Key::Ec(k) => {
                let point = k.public_key().as_ref();
                json!({"kty": "EC", "crv": "P-256", "x": b64(&point[1..33]), "y": b64(&point[33..])})
            }
            Key::Rsa(_, jwk) => jwk.clone(),
        };
        jwk["kid"] = json!(kid);
        jwk["use"] = json!("sig");
        jwk
    }
    fn sign(&self, message: &[u8]) -> Vec<u8> {
        match self {
            Key::Ed(k) => k.sign(message).as_ref().to_vec(),
            Key::Ec(k) => k
                .sign(&SystemRandom::new(), message)
                .unwrap()
                .as_ref()
                .to_vec(),
            Key::Rsa(k, _) => k.sign(message).to_vec(),
        }
    }
    fn token(&self, kid: &str, claims: Value) -> String {
        self.token_with(json!({"alg": self.alg(), "kid": kid, "typ": "JWT"}), claims)
    }
    fn token_with(&self, header: Value, claims: Value) -> String {
        let signing = format!(
            "{}.{}",
            b64(header.to_string().as_bytes()),
            b64(claims.to_string().as_bytes())
        );
        format!("{signing}.{}", b64(&self.sign(signing.as_bytes())))
    }
}

fn jwks(keys: &[(&Key, &str)]) -> String {
    json!({"keys": keys.iter().map(|(k, kid)| k.jwk(kid)).collect::<Vec<_>>()}).to_string()
}

fn claims(h: &Harness, subject: &str) -> Value {
    let now = h.now() / 1000;
    json!({"iss": ISSUER, "aud": AUDIENCE, "sub": subject, "iat": now, "nbf": now - 5, "exp": now + 600})
}

/// Tenant acme with the standard principals and the issuer configured with
/// `key`; alice's IdP subject `sub-alice` is bound to alice.
async fn tenant_with(h: &Harness, key: &Key) -> (String, String, String) {
    let (root, alice, bob) = standard_tenant(h, "acme").await;
    h.service
        .set_oidc_issuer("acme", ISSUER, AUDIENCE, &jwks(&[(key, "k1")]))
        .unwrap();
    let reply = h
        .post(
            "/v1/oidc/bindings",
            &root,
            json!({"issuer": ISSUER, "subject": "sub-alice", "principal": "alice"}),
        )
        .await;
    assert_eq!(reply.status, StatusCode::CREATED, "{}", reply.json);
    (root, alice, bob)
}

#[tokio::test]
async fn id_tokens_of_each_algorithm_authenticate_their_bound_user() {
    for key in [Key::ed(), Key::ec(), Key::rsa()] {
        let h = Harness::new();
        tenant_with(&h, &key).await;
        let token = key.token("k1", claims(&h, "sub-alice"));
        let me = h.get("/v1/whoami", &token).await;
        assert_eq!(me.status, StatusCode::OK, "{}: {}", key.alg(), me.json);
        assert_eq!(me.json["principal"], "alice");
        assert_eq!(me.json["tenant"], "acme");
        assert!(me.json["credential"].as_str().unwrap().starts_with("oidc:"));
        // A token without `kid` verifies against the set too.
        let token = key.token_with(json!({"alg": key.alg()}), claims(&h, "sub-alice"));
        assert_eq!(h.get("/v1/whoami", &token).await.status, StatusCode::OK);
        // Neither the token nor its signature reaches the log.
        let log = h.log.contents();
        let signature = token.rsplit('.').next().unwrap();
        assert!(!log.contains(&token[..40]) && !log.contains(signature));
    }
}

#[tokio::test]
async fn every_oidc_failure_is_the_uniform_401() {
    let h = Harness::new();
    let key = Key::ed();
    let (root, _alice, _bob) = tenant_with(&h, &key).await;
    let other = Key::ed();
    let base = claims(&h, "sub-alice");
    let with = |patch: Value| {
        let mut c = base.clone();
        for (k, v) in patch.as_object().unwrap() {
            if v.is_null() {
                c.as_object_mut().unwrap().remove(k);
            } else {
                c[k] = v.clone();
            }
        }
        c
    };
    let now = h.now() / 1000;
    let bad: Vec<(&str, String)> = vec![
        ("foreign key", other.token("k1", base.clone())),
        ("unknown kid", key.token("k2", base.clone())),
        (
            "issuer",
            key.token("k1", with(json!({"iss": "https://evil.test"}))),
        ),
        (
            "audience",
            key.token("k1", with(json!({"aud": "someone-else"}))),
        ),
        ("expired", key.token("k1", with(json!({"exp": now - 61})))),
        (
            "not yet valid",
            key.token("k1", with(json!({"nbf": now + 61}))),
        ),
        ("no exp", key.token("k1", with(json!({"exp": null})))),
        ("no sub", key.token("k1", with(json!({"sub": null})))),
        (
            "unbound subject",
            key.token("k1", with(json!({"sub": "sub-nobody"}))),
        ),
        (
            "alg none",
            format!(
                "{}.{}.",
                b64(br#"{"alg":"none"}"#),
                b64(base.to_string().as_bytes())
            ),
        ),
        (
            "alg swap",
            key.token_with(json!({"alg": "RS256", "kid": "k1"}), base.clone()),
        ),
        (
            "crit",
            key.token_with(
                json!({"alg": "EdDSA", "kid": "k1", "crit": ["x"]}),
                base.clone(),
            ),
        ),
        ("garbage", "a.b.c".into()),
        (
            "too long",
            key.token("k1", with(json!({"pad": "x".repeat(9000)}))),
        ),
    ];
    let reference = h.get("/v1/whoami", "wvs_nope").await;
    assert_eq!(reference.status, StatusCode::UNAUTHORIZED);
    for (name, token) in &bad {
        let reply = h.get("/v1/whoami", token).await;
        assert_eq!(reply.status, StatusCode::UNAUTHORIZED, "{name}");
        assert_eq!(reply.bytes, reference.bytes, "{name}");
    }
    // Leeway: 60 s past exp still works, more does not (above).
    let edge = key.token("k1", with(json!({"exp": now - 30})));
    assert_eq!(h.get("/v1/whoami", &edge).await.status, StatusCode::OK);

    // Unbinding, suspension, issuer removal and key rotation take effect on
    // the next request.
    let token = key.token("k1", base.clone());
    assert_eq!(h.get("/v1/whoami", &token).await.status, StatusCode::OK);
    h.registry(
        &root,
        json!([{"change": "set_status", "id": "alice", "status": "suspended"}]),
    )
    .await;
    let denied = h.get("/v1/whoami", &token).await;
    assert_eq!(denied.json["error"]["message"], UNAUTHENTICATED_MESSAGE);
    h.registry(
        &root,
        json!([{"change": "set_status", "id": "alice", "status": "active"}]),
    )
    .await;
    assert_eq!(h.get("/v1/whoami", &token).await.status, StatusCode::OK);
    h.service
        .set_oidc_issuer("acme", ISSUER, AUDIENCE, &jwks(&[(&other, "k9")]))
        .unwrap();
    assert_eq!(
        h.get("/v1/whoami", &token).await.status,
        StatusCode::UNAUTHORIZED
    );
    let rotated = other.token("k9", base.clone());
    assert_eq!(h.get("/v1/whoami", &rotated).await.status, StatusCode::OK);
    let reply = h
        .send(
            Method::DELETE,
            &format!("/v1/oidc/bindings?issuer={ISSUER}&subject=sub-alice"),
            Some(&root),
            None,
        )
        .await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    assert_eq!(
        h.get("/v1/whoami", &rotated).await.status,
        StatusCode::UNAUTHORIZED
    );
    h.post(
        "/v1/oidc/bindings",
        &root,
        json!({"issuer": ISSUER, "subject": "sub-alice", "principal": "alice"}),
    )
    .await;
    assert_eq!(h.get("/v1/whoami", &rotated).await.status, StatusCode::OK);
    assert!(h.service.remove_oidc_issuer("acme", ISSUER).unwrap());
    assert_eq!(
        h.get("/v1/whoami", &rotated).await.status,
        StatusCode::UNAUTHORIZED
    );
}

#[tokio::test]
async fn the_tenant_comes_from_the_issuer_configuration() {
    let h = Harness::new();
    let key = Key::ec();
    tenant_with(&h, &key).await;
    let beta_root = h.tenant("beta", "root");
    // The same issuer serves beta under another audience.
    h.service
        .set_oidc_issuer("beta", ISSUER, "weave-beta", &jwks(&[(&key, "k1")]))
        .unwrap();
    // One (issuer, audience) pair names one tenant.
    let clash = h
        .service
        .set_oidc_issuer("beta", ISSUER, AUDIENCE, &jwks(&[(&key, "k1")]));
    assert_eq!(clash.unwrap_err().code, "E_CONFLICT");
    h.post(
        "/v1/oidc/bindings",
        &beta_root,
        json!({"issuer": ISSUER, "subject": "sub-alice", "principal": "root"}),
    )
    .await;
    let alpha_token = key.token("k1", claims(&h, "sub-alice"));
    let mut beta_claims = claims(&h, "sub-alice");
    beta_claims["aud"] = json!(["weave-beta", "unrelated"]);
    let beta_token = key.token("k1", beta_claims);
    let a = h.get("/v1/whoami", &alpha_token).await.json;
    let b = h.get("/v1/whoami", &beta_token).await.json;
    assert_eq!(
        (a["tenant"].as_str(), a["principal"].as_str()),
        (Some("acme"), Some("alice"))
    );
    assert_eq!(
        (b["tenant"].as_str(), b["principal"].as_str()),
        (Some("beta"), Some("root"))
    );
}

#[tokio::test]
async fn group_claims_are_never_live_and_are_imported_with_an_audit_trail() {
    let h = Harness::new();
    let key = Key::ed();
    let (root, alice, bob) = tenant_with(&h, &key).await;
    h.post(
        "/v1/oidc/bindings",
        &root,
        json!({"issuer": ISSUER, "subject": "sub-bob", "principal": "bob"}),
    )
    .await;
    h.post("/v1/graphs", &root, json!({"graph_id": "g"})).await;
    h.registry(
        &root,
        json!([{"change": "grant", "graph_id": "g", "subject": "bob", "permission": "read"}]),
    )
    .await;
    h.seed(
        "acme",
        "root",
        "g",
        vec![node("team-only", &[], &["team"]), node("public", &[], &[])],
    );
    // A token claiming membership of `team` and of the administrators gives
    // bob nothing: claims are not authority.
    let mut c = claims(&h, "sub-bob");
    c["groups"] = json!(["team", "weave:administrators", "eng"]);
    c["roles"] = json!(["admin"]);
    let token = key.token("k1", c);
    let me = h.get("/v1/whoami", &token).await;
    assert_eq!(me.json["principal"], "bob");
    assert_eq!(me.json["administrator"], false);
    assert_eq!(node_ids(&h.query(&token, "g").await), ["public"]);
    assert_eq!(h.get("/v1/audit", &token).await.code(), "E_FORBIDDEN");

    // The import turns an IdP snapshot into audited registry changes.
    let import = |subjects: Value| json!({"issuer": ISSUER, "mapping": {"eng": "team"}, "subjects": subjects});
    let reply = h
        .post(
            "/v1/oidc/groups/import",
            &bob,
            import(json!([{"subject": "sub-bob", "groups": ["eng"]}])),
        )
        .await;
    assert_eq!(reply.code(), "E_FORBIDDEN");
    let reply = h
        .post(
            "/v1/oidc/groups/import",
            &root,
            import(json!([{"subject": "sub-bob", "groups": ["eng"]}, {"subject": "sub-alice", "groups": []}])),
        )
        .await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    assert_eq!(
        reply.json["added"],
        json!([{"group": "team", "member": "bob"}])
    );
    // alice is bound to this issuer and lacks the claim, so the snapshot
    // removes her membership too.
    assert_eq!(
        reply.json["removed"],
        json!([{"group": "team", "member": "alice"}])
    );
    assert_eq!(
        node_ids(&h.query(&token, "g").await),
        ["public", "team-only"]
    );
    let entries = h.audit_entries(&root).await;
    let imported = entries
        .iter()
        .find(|e| e["operation"] == "oidc.groups.import" && e["outcome"] == "ok")
        .unwrap();
    assert_eq!(imported["principal"], "root");
    assert_eq!(imported["graphs"], json!(["weave:registry"]));
    // Registry history records the change as root's write.
    let history = h
        .execute(
            &root,
            json!([{"op": "query", "query": {"graph_id": "weave:registry", "predicate": "weave:member", "to": "team"}}]),
        )
        .await;
    assert!(
        history.bytes.windows(3).any(|w| w == b"bob"),
        "{}",
        history.json
    );
    // A member not bound to the issuer is never touched.
    h.registry(
        &root,
        json!([{"change": "add_principal", "id": "carol", "kind": "user"},
        {"change": "add_member", "group": "team", "member": "carol"}]),
    )
    .await;
    let reply = h
        .post("/v1/oidc/groups/import", &root, import(json!([])))
        .await;
    assert_eq!(
        reply.json["removed"],
        json!([{"group": "team", "member": "bob"}])
    );
    let members = h.get("/v1/registry/groups/team/members", &root).await;
    assert_eq!(members.json["members"], json!(["carol"]));
    assert_eq!(node_ids(&h.query(&token, "g").await), ["public"]);
    // An unchanged snapshot changes nothing.
    let reply = h
        .post("/v1/oidc/groups/import", &root, import(json!([])))
        .await;
    assert_eq!(reply.json["revision"], Value::Null);
    let _ = alice;
}

#[tokio::test]
async fn only_administrators_bind_subjects_and_only_to_users() {
    let h = Harness::new();
    let key = Key::ed();
    let (root, alice, _bob) = tenant_with(&h, &key).await;
    let bind = |principal: &str, issuer: &str| json!({"issuer": issuer, "subject": "s", "principal": principal});
    let reply = h
        .post("/v1/oidc/bindings", &alice, bind("alice", ISSUER))
        .await;
    assert_eq!(reply.code(), "E_FORBIDDEN");
    for principal in ["team", "nobody"] {
        let reply = h
            .post("/v1/oidc/bindings", &root, bind(principal, ISSUER))
            .await;
        assert_eq!(reply.code(), "E_UNAVAILABLE", "{principal}");
    }
    let reply = h
        .post(
            "/v1/oidc/bindings",
            &root,
            bind("alice", "https://unknown.test"),
        )
        .await;
    assert_eq!(reply.code(), "E_UNAVAILABLE");
    let listing = h.get("/v1/oidc/bindings", &root).await;
    assert_eq!(listing.json["bindings"].as_array().unwrap().len(), 1);
    assert_eq!(
        h.get("/v1/oidc/bindings", &alice).await.code(),
        "E_FORBIDDEN"
    );
    // Invalid key sets are refused when configured.
    for bad in [
        "{}",
        r#"{"keys": []}"#,
        r#"{"keys": [{"kty": "RSA", "n": "AQAB", "e": "AQAB"}]}"#,
    ] {
        assert!(
            h.service
                .set_oidc_issuer("acme", ISSUER, AUDIENCE, bad)
                .is_err(),
            "{bad}"
        );
    }
}
